// Plan versions, the pure part: what one version holds on disk, how two
// versions of a file compare, and which OK marks survive a new version.
// hooks/register.tsx writes and reads the files.
import type { OkMark, ParsedFrom, PlanFile, PlanModel, PlanSymbol, PlanVersion, SavedVersion, VersionSource } from '../types'

/** The layout of a saved version file; bump it when the shape changes. */
export const VERSION_SHAPE = 1

type SavedVersionFile = SavedVersion & { shape: number }

export function buildSavedVersion(args: {
  version: number
  receivedAt: string
  markdown: string
  plan: PlanModel
  parsedFrom: ParsedFrom
  warnings: readonly string[]
  source: VersionSource
  from?: number
}): SavedVersion {
  return {
    version: args.version,
    receivedAt: args.receivedAt,
    markdown: args.markdown,
    plan: args.plan,
    parsedFrom: args.parsedFrom,
    warnings: [...args.warnings],
    source: args.source,
    ...(args.from !== undefined ? { from: args.from } : {}),
  }
}

/** The text written to a version file. */
export function serializeVersion(saved: SavedVersion): string {
  const file: SavedVersionFile = { shape: VERSION_SHAPE, ...saved }
  return JSON.stringify(file)
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/** The version a file holds, or null when the text is not one this code wrote. */
export function parseSavedVersion(text: string): SavedVersion | null {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return null
  }
  if (!isObject(raw) || raw.shape !== VERSION_SHAPE) return null
  const { version, receivedAt, markdown, plan, parsedFrom, warnings, source, from } = raw
  if (typeof version !== 'number' || typeof receivedAt !== 'string' || typeof markdown !== 'string') return null
  if (!isObject(plan) || typeof plan.title !== 'string' || typeof plan.summary !== 'string' || !Array.isArray(plan.files) || !isObject(plan.task)) return null
  const parsed: ParsedFrom = parsedFrom === 'block' || parsedFrom === 'model' || parsedFrom === 'markdown' ? parsedFrom : 'none'
  const origin: VersionSource = source === 'restored' || source === 'edited' ? source : 'received'
  return {
    version,
    receivedAt,
    markdown,
    plan: plan as unknown as PlanModel,
    parsedFrom: parsed,
    warnings: Array.isArray(warnings) ? warnings.filter((one): one is string => typeof one === 'string') : [],
    source: origin,
    ...(typeof from === 'number' ? { from } : {}),
  }
}

/** The row the state keeps for a saved version. */
export function versionEntry(saved: SavedVersion, path: string): PlanVersion {
  return {
    version: saved.version,
    receivedAt: saved.receivedAt,
    title: saved.plan.title,
    fileCount: saved.plan.files.length,
    source: saved.source,
    ...(saved.from !== undefined ? { from: saved.from } : {}),
    path,
  }
}

function symbolKey(symbol: PlanSymbol): string {
  return JSON.stringify([symbol.name, symbol.kind, symbol.signature, symbol.description, symbol.anchor ?? '', symbol.change ?? 'new'])
}

/** Whether two versions plan the same thing for a file: same status, description and symbols. */
export function sameFile(a: PlanFile | undefined, b: PlanFile | undefined): boolean {
  if (!a || !b) return false
  if (a.status !== b.status || a.description !== b.description || a.symbols.length !== b.symbols.length) return false
  return a.symbols.every((symbol, index) => symbolKey(symbol) === symbolKey(b.symbols[index] as PlanSymbol))
}

/**
 * The OK marks that still hold after a new version: a mark stays while its
 * file is planned the same way; a changed or dropped file loses its mark.
 */
export function keepOkMarks(marks: Readonly<Record<string, OkMark>>, previous: PlanModel | null, next: PlanModel): Record<string, OkMark> {
  if (!previous) return {}
  const before = new Map(previous.files.map(file => [file.path, file]))
  const after = new Map(next.files.map(file => [file.path, file]))
  const kept: Record<string, OkMark> = {}
  for (const [path, mark] of Object.entries(marks)) {
    if (sameFile(before.get(path), after.get(path))) kept[path] = mark
  }
  return kept
}

/** The paths a folder mark covers: every planned file under `dir/`. */
export function pathsUnderFolder(plan: PlanModel, folder: string): string[] {
  const prefix = folder.endsWith('/') ? folder : `${folder}/`
  return plan.files.filter(file => file.path.startsWith(prefix)).map(file => file.path)
}

files.hooks/web.ts:
// The mod's side of the review page, the pure part: what the page may ask
// (actions), what the mod sends it (the snapshot) and the server's stdout
// protocol. Nothing here touches `$`; register.tsx wires it.
import type {
  CommentTarget,
  Diagram,
  Explanation,
  FileCache,
  GeneratedBody,
  Lang,
  LoadedVersion,
  OkMark,
  PlanModel,
  PlanVersion,
  QaItem,
  Review,
  ReviewComment,
  WebFileEntry,
  WebNotice,
  WebSnapshot,
} from '../types'
import { deletedDiff, newFileStub, stubDiff } from './diff'

export type WebAction =
  | { type: 'comment'; target: CommentTarget; text: string }
  | { type: 'deleteComment'; id: string }
  | { type: 'submit' }
  | { type: 'loadFile'; path: string }
  | { type: 'generateBody'; path: string; symbol: string }
  | { type: 'ask'; id?: string; question: string; focus?: string; target?: CommentTarget }
  | { type: 'askMore'; id: string; question: string }
  | { type: 'explain'; id: string; target: CommentTarget; focus?: string }
  | { type: 'setOk'; paths: string[]; ok: boolean }
  | { type: 'editSummary'; text: string }
  | { type: 'viewVersion'; version: number | null }
  | { type: 'compareWith'; version: number | null }
  | { type: 'restoreVersion'; version: number }
  | { type: 'generateDiagram' }
  | { type: 'callers'; path: string; symbol: string }
  | { type: 'diagramSvg'; svg: string }
  | { type: 'setLang'; lang: Lang }
  | { type: 'ping' }

export type ServerMessage =
  | { type: 'listening'; host: string; port: number; token: string; url: string }
  | { type: 'action'; action: unknown }
  | { type: 'log'; text: string }
  | { type: 'fatal'; text: string }

const MAX_TEXT = 20000
/** How long an edited summary may be: the plan file holds it whole. */
const MAX_SUMMARY = 400_000

/**
 * The shape of the state and the set of actions the mod understands. The page
 * carries the same number and warns when they differ: a session keeps the mod
 * it loaded at its start, while the server serves the page files from disk,
 * so after an update of the mod an open session shows a newer page.
 */
import { WEB_PROTOCOL } from './state'

export { WEB_PROTOCOL }

const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null && !Array.isArray(value)
const str = (value: unknown, limit = MAX_TEXT): string | undefined => (typeof value === 'string' ? value.slice(0, limit) : undefined)
const num = (value: unknown): number | undefined => (typeof value === 'number' && Number.isFinite(value) ? value : undefined)
const ID = /^[A-Za-z0-9_-]{1,64}$/

export function parseTarget(raw: unknown): CommentTarget {
  const target: CommentTarget = {}
  if (!isRecord(raw)) return target
  const path = str(raw.path, 2000)
  if (path) target.path = path
  const symbol = str(raw.symbol, 500)
  if (symbol) target.symbol = symbol
  const selection = str(raw.selection, 2000)
  if (selection) target.selection = selection
  if (Array.isArray(raw.lines) && raw.lines.length === 2) {
    const a = num(raw.lines[0])
    const b = num(raw.lines[1])
    if (a !== undefined && b !== undefined) target.lines = [Math.min(a, b), Math.max(a, b)]
  }
  return target
}

/** A plan version number as the page names one: a positive whole number; null for "the current plan". */
function versionArg(raw: unknown): number | null | undefined {
  if (raw === null || raw === undefined) return null
  const value = num(raw)
  return value !== undefined && value >= 1 && Number.isInteger(value) ? value : undefined
}

export function parseAction(raw: unknown): WebAction | null {
  if (!isRecord(raw) || typeof raw.type !== 'string') return null
  switch (raw.type) {
    case 'comment': {
      const text = str(raw.text)?.trim()
      if (!text) return null
      return { type: 'comment', target: parseTarget(raw.target), text }
    }
    case 'deleteComment': {
      const id = str(raw.id, 64)
      return id ? { type: 'deleteComment', id } : null
    }
    case 'submit':
      return { type: 'submit' }
    case 'loadFile': {
      const path = str(raw.path, 2000)
      return path ? { type: 'loadFile', path } : null
    }
    case 'generateBody': {
      const path = str(raw.path, 2000)
      const symbol = str(raw.symbol, 500)
      return path && symbol ? { type: 'generateBody', path, symbol } : null
    }
    case 'ask': {
      const question = str(raw.question)?.trim()
      if (!question) return null
      const focus = str(raw.focus, 2000)
      const target = raw.target === undefined ? undefined : parseTarget(raw.target)
      const hasTarget = target !== undefined && Object.keys(target).length > 0
      const id = str(raw.id, 64)
      const validId = id && ID.test(id) ? id : undefined
      return { type: 'ask', question, ...(validId ? { id: validId } : {}), ...(focus ? { focus } : {}), ...(hasTarget ? { target } : {}) }
    }
    case 'askMore': {
      const id = str(raw.id, 64)
      const question = str(raw.question)?.trim()
      return id && question ? { type: 'askMore', id, question } : null
    }
    case 'explain': {
      const id = str(raw.id, 64)
      if (!id || !ID.test(id)) return null
      const focus = str(raw.focus, 2000)
      return { type: 'explain', id, target: parseTarget(raw.target), ...(focus ? { focus } : {}) }
    }
    case 'setOk': {
      const list = Array.isArray(raw.paths) ? raw.paths : [raw.path]
      const paths = [...new Set(list.map(one => str(one, 2000)).filter((one): one is string => Boolean(one)))]
      return paths.length ? { type: 'setOk', paths, ok: raw.ok !== false } : null
    }
    case 'editSummary': {
      const text = str(raw.text, MAX_SUMMARY)
      return typeof text === 'string' ? { type: 'editSummary', text: text.replace(/\r\n?/g, '\n').trimEnd() } : null
    }
    case 'viewVersion': {
      const version = versionArg(raw.version)
      return version === undefined ? null : { type: 'viewVersion', version }
    }
    case 'compareWith': {
      const version = versionArg(raw.version)
      return version === undefined ? null : { type: 'compareWith', version }
    }
    case 'restoreVersion': {
      const version = versionArg(raw.version)
      return version ? { type: 'restoreVersion', version } : null
    }
    case 'generateDiagram':
      return { type: 'generateDiagram' }
    case 'callers': {
      const path = str(raw.path, 2000)
      const symbol = str(raw.symbol, 500)
      return path && symbol ? { type: 'callers', path, symbol } : null
    }
    case 'diagramSvg': {
      const svg = str(raw.svg, 2_000_000)
      return svg && svg.trimStart().startsWith('<svg') ? { type: 'diagramSvg', svg } : null
    }
    case 'setLang':
      return { type: 'setLang', lang: raw.lang === 'uk' ? 'uk' : 'en' }
    case 'ping':
      return { type: 'ping' }
    default:
      return null
  }
}

/** Splits a stream of text into whole lines; `rest` is the unfinished tail. */
export function splitLines(buffer: string, text: string): { lines: string[]; rest: string } {
  const joined = buffer + text
  const parts = joined.split('\n')
  const rest = parts.pop() ?? ''
  return { lines: parts.filter(line => line.trim() !== ''), rest }
}

export function parseServerLine(line: string): ServerMessage | null {
  let parsed: unknown
  try {
    parsed = JSON.parse(line)
  } catch {
    return { type: 'log', text: line }
  }
  if (!isRecord(parsed) || typeof parsed.type !== 'string') return null
  if (parsed.type === 'listening') {
    const port = num(parsed.port)
    const token = str(parsed.token, 200)
    const url = str(parsed.url, 500)
    const host = str(parsed.host, 200) ?? '127.0.0.1'
    return port !== undefined && token && url ? { type: 'listening', host, port, token, url } : null
  }
  if (parsed.type === 'action') return { type: 'action', action: parsed.action }
  if (parsed.type === 'fatal') return { type: 'fatal', text: str(parsed.text) ?? 'fatal' }
  return { type: 'log', text: str(parsed.text) ?? line }
}

export function pageUrl(baseUrl: string, token: string): string {
  return `${baseUrl}/?t=${encodeURIComponent(token)}`
}

/** The commands that open a URL, one per platform; the first that exits 0 wins. */
export function openCommands(url: string): string[][] {
  return [
    ['open', url],
    ['xdg-open', url],
    ['cmd', '/c', 'start', '', url],
  ]
}

export function fileEntries(plan: PlanModel | null, files: FileCache): Record<string, WebFileEntry> {
  const entries: Record<string, WebFileEntry> = {}
  if (!plan) return entries
  for (const file of plan.files) {
    if (file.status === 'new') {
      entries[file.path] = { loaded: true, view: { format: 'source', text: newFileStub(file), startLine: 1 } }
      continue
    }
    if (!(file.path in files)) {
      entries[file.path] = { loaded: false }
      continue
    }
    const content = files[file.path]
    if (typeof content !== 'string') {
      entries[file.path] = { loaded: true, missing: true }
      continue
    }
    const text = file.status === 'deleted' ? deletedDiff(content) : stubDiff(content, file)
    entries[file.path] = { loaded: true, view: { format: 'diff', text } }
  }
  return entries
}

export function buildSnapshot(args: {
  plan: PlanModel | null
  review: Review
  comments: ReviewComment[]
  bodies: Record<string, GeneratedBody>
  qa: QaItem[]
  diagram: Diagram
  files: FileCache
  ok?: Record<string, OkMark>
  explanations?: Record<string, Explanation>
  versions?: PlanVersion[]
  compare?: LoadedVersion | null
  viewing?: LoadedVersion | null
  lang: Lang
  summaryLimit: number
  cwd: string
  notice?: WebNotice
  nowMs: number
}): WebSnapshot {
  return {
    plan: args.plan,
    review: args.review,
    comments: args.comments,
    bodies: args.bodies,
    qa: args.qa,
    diagram: args.diagram,
    files: fileEntries(args.plan, args.files),
    ok: args.ok ?? {},
    explanations: args.explanations ?? {},
    versions: args.versions ?? [],
    ...(args.compare ? { compare: args.compare } : {}),
    ...(args.viewing ? { viewing: { ...args.viewing, files: fileEntries(args.viewing.plan, args.files) } } : {}),
    lang: args.lang,
    summaryLimit: args.summaryLimit,
    cwd: args.cwd,
    ...(args.notice ? { notice: args.notice } : {}),
    generatedAt: new Date(args.nowMs).toISOString(),
    protocol: WEB_PROTOCOL,
  }
}

